// "Good chances" (owner, 4 Oct; ENGINE-PLANS-MATTER §3b): how many goals a
// side's shots were worth, from the engine's own read of each shot at the
// strike (the compact replay's `q`, lib/ballers/compute.ts) turned into a goal
// chance by a calibration table measured on THIS engine build
// (lib/ballers/chances-table.ts, generated by
// packages/football-engine/evidence/2026-10-04-practice-chances/). A shot the
// engine doesn't read (header, volley, direct free kick: `sk`) counts its
// kind's rate. A match's good chances = the sum over its shots.
//
// Honest thin: the number is shown only beside an anchor from the same
// player's own matches (the opponent in the same match, or their other setup
// against the same opponent), never against a league norm, never as odds.
// It is never shown when the match was played on an engine build the table
// does not hold (the build it was measured on, or one proven byte-identical
// to it: `builds`), or when any shot lacks a read (a replay stored before
// 4 Oct): null, and the caller shows nothing.
//
// Pure: no I/O, no React.
import {CHANCE_TABLE} from './chances-table';
export {CHANCE_TABLE};
import type {ReplayEvent,ReplayHeader} from './replay';

export interface ChanceTable {
 /** The ENGINE_BUILD the table was measured on (full hash). */ build:string;
 /** Every build the table holds for (full hashes): the measured `build` first, then each build whose engine was
  * proven byte-identical to it (the same matches, frame for frame: engine as data, 2026-10-21). A table without the
  * list holds for its `build` alone. */ builds?:readonly string[];
 /** Monotone fit of goal rate on the engine's quality read: knots [q, rate],
  * q ascending; linear between knots, flat beyond the ends. */ knots:readonly (readonly [number,number])[];
 /** Goal rate of the shots without a read: 1 header, 2 volley, 3 direct free kick. */ kinds:Readonly<Record<1|2|3,number>>;
 /** Per-match sd of (your good chances - theirs) between kick-offs of one fixed setup, full match (900 s). */ sdDiff:number;
 /** Per-match sd of one side's good chances between kick-offs of one fixed setup, full match. */ sdFor:number;
 /** What it was measured on. */ matches:number;shots:number;
}

/** One read shot's goal chance (0-1). */
export function rateOf(q:number,table:ChanceTable=CHANCE_TABLE):number{
 const k=table.knots;
 if(!k.length)return 0;
 if(q<=k[0][0])return k[0][1];
 for(let i=1;i<k.length;i++)if(q<=k[i][0]){const [q0,r0]=k[i-1],[q1,r1]=k[i];return q1===q0?r1:r0+(r1-r0)*(q-q0)/(q1-q0);}
 return k[k.length-1][1];
}
/** A shot event's goal chance; null when it carries no read (a replay from before 4 Oct). */
export function shotChance(e:Pick<ReplayEvent,'q'|'sk'>,table:ChanceTable=CHANCE_TABLE):number|null{
 if(typeof e.q==='number'&&Number.isFinite(e.q))return rateOf(e.q,table);
 if(e.sk===1||e.sk===2||e.sk===3)return table.kinds[e.sk];
 return null;
}

/** The side of a shot event: its own `s`, else its shooter's. */
const sideOf=(e:Pick<ReplayEvent,'s'|'a'>,players:Pick<ReplayHeader,'players'>['players']):0|1|null=>{
 if(e.s===0||e.s===1)return e.s;
 const p=e.a===undefined?undefined:players.find(x=>x.i===e.a);
 return p?p.side:null;
};

/** The builds a table holds for: its `builds`, or its measured `build` alone. */
export const tableBuilds=(table:ChanceTable=CHANCE_TABLE):readonly string[]=>table.builds??[table.build];

/** Both sides' good chances in one match, [side 0, side 1]; null unless the
 * match was played on a build the table holds for and every shot carries a read. */
export function matchChances(events:readonly Pick<ReplayEvent,'k'|'q'|'sk'|'s'|'a'>[],header:Pick<ReplayHeader,'players'>,build:string|null|undefined,table:ChanceTable=CHANCE_TABLE):[number,number]|null{
 if(!build||!tableBuilds(table).includes(build))return null;
 const sum:[number,number]=[0,0];
 for(const e of events){
  if(e.k!=='shot')continue;
  const c=shotChance(e,table),side=sideOf(e,header.players);
  if(c===null||side===null)return null;
  sum[side]+=c;
 }
 return sum;
}

/** One decimal, as the player reads it ("3.4"). */
export const chanceText=(v:number)=>(Math.round(v*10)/10).toFixed(1);
